const fs = require('fs');
const path = require('path');

// ============================================================
// ETERNAL GUILD ASSET IMAGES · CONFIG + LOAD JOBS
// Edit ONLY the CONFIG block below. Everything else reads from
// tools/n8n/asset_prompts.json in the game repo.
// ============================================================

// ---------- CONFIG ----------
// The Godot project / eternal_guild git clone, as a WSL path.
const PROJECT_DIR = '/mnt/f/GAME I AM MAKING/shiningsun';
// Art working folder OUTSIDE the Godot project (images, picks, gallery).
const ART_DIR = '/mnt/f/GAME I AM MAKING/eternal_guild_art';
// Gemini image model ("Nano Banana"). Same model as the sticker pipeline.
const MODEL = 'gemini-2.5-flash-image';
// Safety cap: never generate more than this many images in one run.
const MAX_IMAGES_PER_RUN = 30;
// ----------------------------

const PROMPTS_FILE = path.join(PROJECT_DIR, 'tools', 'n8n', 'asset_prompts.json');
const GEN_DIR = path.join(ART_DIR, 'generated');
const PICKED_DIR = path.join(ART_DIR, 'picked');
const STATUS_FILE = path.join(GEN_DIR, 'status.json');

if (!fs.existsSync(PROMPTS_FILE)) {
  throw new Error('Prompts file not found: ' + PROMPTS_FILE + '. Check PROJECT_DIR in this node, and that the repo is pulled.');
}
[ART_DIR, GEN_DIR, PICKED_DIR, path.join(ART_DIR, 'refs')].forEach(d => {
  if (!fs.existsSync(d)) fs.mkdirSync(d, { recursive: true });
});

let spec;
try { spec = JSON.parse(fs.readFileSync(PROMPTS_FILE, 'utf8')); }
catch (e) { throw new Error('asset_prompts.json is not valid JSON: ' + e.message); }

// A corrupt status file must NOT silently reset: that would re-generate (and re-pay for) everything.
let status = {};
if (fs.existsSync(STATUS_FILE)) {
  try { status = JSON.parse(fs.readFileSync(STATUS_FILE, 'utf8')); }
  catch (e) { throw new Error('status.json is corrupt. Fix it or rename it (everything will regenerate): ' + STATUS_FILE); }
}

// Small dependency-free hash (only fs/path/https are required, same as the sticker pipeline).
function fnv(str, seed) {
  let h = seed >>> 0;
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619) >>> 0; }
  return h.toString(16).padStart(8, '0');
}
function hash(str) { return fnv(str, 2166136261) + fnv(str, 0x9747b28c); }

// Refs are relative to ART_DIR (or absolute). picked/K1.png also matches picked/K1.jpg/.jpeg/.webp.
function resolveRef(rel) {
  const abs = path.isAbsolute(rel) ? rel : path.join(ART_DIR, rel);
  if (fs.existsSync(abs)) return abs;
  const base = abs.replace(/\.(png|jpe?g|webp)$/i, '');
  for (const ext of ['.png', '.jpg', '.jpeg', '.webp']) {
    if (fs.existsSync(base + ext)) return base + ext;
  }
  return null;
}
function slug(s) { return String(s).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, ''); }

const jobs = Array.isArray(spec.jobs) ? spec.jobs : [];
const viewsTemplate = spec.views_template || '';
const seen = new Set();
const todo = [];
const waiting = [];
const disabled = [];
let alreadyDone = 0;

for (const job of jobs) {
  if (!job.id || !job.stage) throw new Error('Every job needs "id" and "stage": ' + JSON.stringify(job).slice(0, 150));
  const jobKey = job.id + '|' + job.stage;
  if (seen.has(jobKey)) throw new Error('Duplicate job in asset_prompts.json: ' + job.id + ' (' + job.stage + ')');
  seen.add(jobKey);

  if (job.enabled === false) { disabled.push(job.id + ' (' + job.stage + ')'); continue; }

  const refsRel = Array.isArray(job.refs) ? job.refs : [];
  const refsAbs = refsRel.map(resolveRef);
  const missing = refsRel.filter((r, i) => !refsAbs[i]);
  if (missing.length) { waiting.push({ id: job.id, stage: job.stage, needs: missing }); continue; }

  // Changing a picked reference image (new size/mtime) re-generates everything built from it.
  const refFingerprint = refsAbs.map(a => { const st = fs.statSync(a); return a + ':' + st.size + ':' + Math.round(st.mtimeMs); }).join('|');

  let shots;
  if (job.stage === 'views') {
    if (!viewsTemplate.includes('{view}')) throw new Error('views_template in asset_prompts.json must contain {view}');
    if (!Array.isArray(job.views) || job.views.length === 0) throw new Error('Job ' + job.id + ' (views) has no "views" list');
    shots = job.views.map(v => ({ view: v, prompt: viewsTemplate.replace('{view}', v) + (job.prompt ? ' ' + job.prompt : '') }));
  } else {
    if (!job.prompt || !String(job.prompt).trim()) throw new Error('Job ' + job.id + ' has an empty prompt');
    shots = [{ view: '', prompt: String(job.prompt).trim() }];
  }

  const variants = Math.max(1, parseInt(job.variants || 1, 10));
  const aspect = job.aspect || '1:1';
  const rev = job.rev || 1;

  for (const shot of shots) {
    for (let v = 1; v <= variants; v++) {
      const key = hash([MODEL, job.id, job.stage, shot.view, v, aspect, rev, shot.prompt, refFingerprint].join('\n'));
      const prev = status[key];
      if (prev && prev.file && fs.existsSync(prev.file)) { alreadyDone++; continue; }

      const viewPart = shot.view ? '__' + slug(shot.view) : '';
      const fileName = job.id + viewPart + '__v' + v + '__' + key.slice(0, 8) + '.png';
      todo.push({
        key,
        id: job.id,
        stage: job.stage,
        view: shot.view,
        variant: v,
        aspect,
        rev,
        prompt: shot.prompt,
        refs_rel: refsRel,
        refs_abs: refsAbs,
        model: MODEL,
        out_path: path.join(GEN_DIR, job.stage, job.id, fileName),
        art_dir: ART_DIR,
        gen_dir: GEN_DIR,
        status_file: STATUS_FILE,
      });
    }
  }
}

const batch = todo.slice(0, MAX_IMAGES_PER_RUN);
const plan = {
  to_generate: batch.length,
  deferred_to_next_run: todo.length - batch.length,
  already_done: alreadyDone,
  waiting_on_picks: waiting,
  disabled,
};
console.log('Plan:', JSON.stringify(plan));

if (batch.length === 0) {
  return [{ json: { _nothing_to_do: true, _plan: plan, art_dir: ART_DIR, gen_dir: GEN_DIR, status_file: STATUS_FILE } }];
}
return batch.map(j => ({ json: { ...j, _plan: plan } }));

const fs = require('fs');
const path = require('path');
const https = require('https');

// ============================================================
// GENERATE + SAVE: one image per item.
// The image is written to disk right after it arrives, so a later
// failure in the batch never loses images that were already paid for.
// A failed item returns { error } instead of stopping the whole run.
// ============================================================

const d = $input.item.json;
if (d._nothing_to_do) return [{ json: d }];

const GEMINI_KEY = $env.GEMINI_API_KEY;
if (!GEMINI_KEY) throw new Error('GEMINI_API_KEY not set');

function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }
function request(options, body) {
  return new Promise((resolve, reject) => {
    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        let parsed = null;
        try { parsed = JSON.parse(data); } catch (e) {}
        resolve({ status: res.statusCode, body: parsed, raw: data });
      });
    });
    req.on('error', reject);
    req.setTimeout(180000, () => req.destroy(new Error('Request timed out after 180s')));
    if (body) req.write(body);
    req.end();
  });
}

await sleep(3000); // rate-limit cushion (same as the sticker pipeline)

// Reference images first, then the text prompt.
const mimeMap = { png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', webp: 'image/webp' };
const parts = [];
for (const refPath of (d.refs_abs || [])) {
  const ext = refPath.split('.').pop().toLowerCase();
  parts.push({ inlineData: { mimeType: mimeMap[ext] || 'image/png', data: fs.readFileSync(refPath).toString('base64') } });
}
parts.push({ text: d.prompt });

const body = JSON.stringify({
  contents: [{ parts }],
  generationConfig: {
    responseModalities: ['TEXT', 'IMAGE'],
    imageConfig: { aspectRatio: d.aspect || '1:1' }
  }
});

const MAX_RETRIES = 2;
let imagePart = null;
let lastError = '';

for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
  if (attempt > 0) {
    const wait = /429|RESOURCE_EXHAUSTED/.test(lastError) ? 20000 * attempt : 3000;
    console.log(`Retry ${attempt}/${MAX_RETRIES} for ${d.id} in ${wait / 1000}s (${lastError.slice(0, 120)})`);
    await sleep(wait);
  }
  let resp;
  try {
    resp = await request({
      hostname: 'generativelanguage.googleapis.com',
      path: `/v1beta/models/${d.model}:generateContent`,
      method: 'POST',
      headers: {
        'x-goog-api-key': GEMINI_KEY,
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(body)
      }
    }, body);
  } catch (e) {
    lastError = 'network: ' + e.message;
    continue;
  }

  const b = resp.body;
  if (!b) { lastError = `HTTP ${resp.status}, unreadable response: ${String(resp.raw).slice(0, 200)}`; continue; }
  if (b.error) { lastError = `HTTP ${resp.status} ${b.error.status || ''}: ${b.error.message || JSON.stringify(b.error)}`; continue; }
  if (b.promptFeedback?.blockReason) { lastError = 'Prompt blocked: ' + b.promptFeedback.blockReason; break; } // retrying won't help

  const cand = b.candidates?.[0];
  const outParts = cand?.content?.parts || [];
  imagePart = outParts.find(p => p.inlineData?.data);
  if (imagePart) break;
  const text = outParts.find(p => p.text)?.text || '';
  lastError = `No image returned (finishReason: ${cand?.finishReason || 'none'}) ${text.slice(0, 200)}`;
}

if (!imagePart) {
  console.log('FAILED:', d.id, d.view, 'v' + d.variant, lastError);
  return [{ json: { id: d.id, stage: d.stage, view: d.view, variant: d.variant, error: lastError, _plan: d._plan, art_dir: d.art_dir, gen_dir: d.gen_dir, status_file: d.status_file } }];
}

// ---- Save the image ----
fs.mkdirSync(path.dirname(d.out_path), { recursive: true });
const buffer = Buffer.from(imagePart.inlineData.data, 'base64');
fs.writeFileSync(d.out_path, buffer);
const createdAt = new Date().toISOString();
console.log('Saved:', d.out_path, '(' + Math.round(buffer.length / 1024) + ' KB)');

// ---- Record it in status.json (what's done, so re-runs skip it) ----
let status = {};
if (fs.existsSync(d.status_file)) {
  try { status = JSON.parse(fs.readFileSync(d.status_file, 'utf8')); }
  catch (e) { throw new Error('status.json became unreadable mid-run: ' + d.status_file); }
}
status[d.key] = {
  file: d.out_path, id: d.id, stage: d.stage, view: d.view, variant: d.variant,
  aspect: d.aspect, rev: d.rev, model: d.model, refs: d.refs_rel, prompt: d.prompt, created: createdAt
};
fs.writeFileSync(d.status_file, JSON.stringify(status, null, 2));

// ---- Append to catalog.csv (your AI-generation log, e.g. for Steam's disclosure form) ----
const catalogPath = path.join(d.gen_dir, 'catalog.csv');
function csvField(val) {
  const str = val === null || val === undefined ? '' : String(val);
  return /[",\n]/.test(str) ? '"' + str.replace(/"/g, '""') + '"' : str;
}
if (!fs.existsSync(catalogPath)) {
  fs.writeFileSync(catalogPath, 'date,file,id,stage,view,variant,model,aspect,refs,prompt\n');
}
fs.appendFileSync(catalogPath, [
  createdAt, path.basename(d.out_path), d.id, d.stage, d.view, d.variant, d.model, d.aspect,
  (d.refs_rel || []).join(' | '), d.prompt
].map(csvField).join(',') + '\n');

return [{ json: {
  id: d.id, stage: d.stage, view: d.view, variant: d.variant,
  file: d.out_path, size_kb: Math.round(buffer.length / 1024),
  _plan: d._plan, art_dir: d.art_dir, gen_dir: d.gen_dir, status_file: d.status_file
} }];

const fs = require('fs');
const path = require('path');

// ============================================================
// REPORT + GALLERY
// Writes <ART_DIR>/generated/index.html with EVERY image generated so
// far (not just this run), grouped by asset, and tells you what to
// copy into picked/ to unlock the next layer.
// ============================================================

const items = $input.all().map(i => i.json);
const first = items[0] || {};
const plan = first._plan || {};
const ART_DIR = first.art_dir;
const GEN_DIR = first.gen_dir;
const STATUS_FILE = first.status_file;
if (!GEN_DIR || !STATUS_FILE) throw new Error('Report node got no paths. Did "Load Jobs" run?');

const ok = items.filter(i => i.file);
const failed = items.filter(i => i.error);

let status = {};
if (fs.existsSync(STATUS_FILE)) {
  try { status = JSON.parse(fs.readFileSync(STATUS_FILE, 'utf8')); } catch (e) {}
}

function esc(s) {
  return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
function rel(p) { return path.relative(GEN_DIR, p).split(path.sep).map(encodeURIComponent).join('/'); }
function winPath(p) {
  const m = /^\/mnt\/([a-z])\/(.*)$/i.exec(p);
  return m ? m[1].toUpperCase() + ':\\' + m[2].replace(/\//g, '\\') : p;
}
function isPicked(id) {
  return ['.png', '.jpg', '.jpeg', '.webp'].some(ext => fs.existsSync(path.join(ART_DIR, 'picked', id + ext)));
}

// Group all recorded images by stage + id, newest first.
const STAGE_ORDER = { keyart: 0, concept: 1, views: 2 };
const groups = {};
for (const rec of Object.values(status)) {
  if (!rec.file || !fs.existsSync(rec.file)) continue;
  const k = rec.stage + '|' + rec.id;
  (groups[k] = groups[k] || { stage: rec.stage, id: rec.id, recs: [] }).recs.push(rec);
}
const ordered = Object.values(groups).sort((a, b) =>
  ((STAGE_ORDER[a.stage] ?? 9) - (STAGE_ORDER[b.stage] ?? 9)) || a.id.localeCompare(b.id));

const justMade = new Set(ok.map(i => i.file));
let sections = '';
for (const g of ordered) {
  g.recs.sort((a, b) => String(b.created).localeCompare(String(a.created)));
  const pickable = g.stage !== 'views';
  const picked = pickable && isPicked(g.id);
  const hint = pickable
    ? (picked
      ? `<span class="badge done">picked ✓</span>`
      : `<span class="badge todo">pick one → copy it to <code>picked/${esc(g.id)}.png</code></span>`)
    : `<span class="badge info">reference views → give these to Claude in Blender</span>`;
  const cards = g.recs.map(r => `
      <figure class="${justMade.has(r.file) ? 'new' : ''}">
        <a href="${rel(r.file)}" target="_blank"><img loading="lazy" src="${rel(r.file)}" alt="${esc(r.id)}"></a>
        <figcaption>
          <b>${esc(r.view ? r.view + ' · ' : '')}v${esc(r.variant)}</b>${justMade.has(r.file) ? ' <span class="new-tag">new</span>' : ''}<br>
          <code>${esc(path.basename(r.file))}</code>
        </figcaption>
      </figure>`).join('');
  sections += `
  <section>
    <h2><span class="stage">${esc(g.stage)}</span> ${esc(g.id)} ${hint}</h2>
    <details><summary>prompt</summary><p>${esc(g.recs[0].prompt)}</p></details>
    <div class="grid">${cards}</div>
  </section>`;
}

const waitingList = (plan.waiting_on_picks || []).map(w =>
  `<li><b>${esc(w.id)}</b> (${esc(w.stage)}) needs <code>${w.needs.map(esc).join('</code>, <code>')}</code></li>`).join('');
const failedList = failed.map(f =>
  `<li><b>${esc(f.id)}</b> ${esc(f.view || '')} v${esc(f.variant)}: ${esc(f.error)}</li>`).join('');

const html = `<!doctype html>
<html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Eternal Guild Asset Images</title>
<style>
  :root { --bg:#16181d; --panel:#1f232a; --ink:#e8e4dc; --muted:#9a968e; --line:#2e333b; --accent:#3fe0c8; --warn:#f0a35e; --bad:#e0306a; }
  * { box-sizing: border-box; }
  body { margin:0; padding:24px 16px 64px; background:var(--bg); color:var(--ink); font:15px/1.5 system-ui, sans-serif; }
  main { max-width:1200px; margin:0 auto; }
  h1 { font-size:22px; margin:0 0 4px; }
  .sub { color:var(--muted); margin:0 0 20px; }
  .box { background:var(--panel); border:1px solid var(--line); border-radius:8px; padding:12px 16px; margin:0 0 16px; }
  .box h3 { margin:0 0 6px; font-size:15px; }
  section { border-top:1px solid var(--line); padding:18px 0; }
  h2 { font-size:17px; margin:0 0 6px; display:flex; flex-wrap:wrap; gap:8px; align-items:center; }
  .stage { font-size:12px; text-transform:uppercase; letter-spacing:.06em; color:var(--muted); border:1px solid var(--line); border-radius:4px; padding:1px 6px; }
  .badge { font-size:12px; font-weight:500; border-radius:4px; padding:2px 8px; }
  .badge.todo { background:rgba(240,163,94,.15); color:var(--warn); }
  .badge.done { background:rgba(63,224,200,.15); color:var(--accent); }
  .badge.info { background:rgba(154,150,142,.15); color:var(--muted); }
  details { color:var(--muted); margin:0 0 10px; }
  details p { margin:6px 0 0; max-width:80ch; }
  .grid { display:grid; grid-template-columns:repeat(auto-fill, minmax(240px, 1fr)); gap:12px; }
  figure { margin:0; background:var(--panel); border:1px solid var(--line); border-radius:8px; overflow:hidden; }
  figure.new { border-color:var(--accent); }
  figure img { display:block; width:100%; height:auto; background:#0e0f12; }
  figcaption { padding:8px 10px; font-size:13px; color:var(--muted); word-break:break-all; }
  figcaption b { color:var(--ink); }
  .new-tag { color:var(--accent); font-weight:600; }
  code { font-size:12px; }
  ul { margin:4px 0 0; padding-left:20px; }
</style></head>
<body><main>
  <h1>Eternal Guild Asset Images</h1>
  <p class="sub">Last run ${esc(new Date().toLocaleString())}: ${ok.length} generated, ${failed.length} failed, ${esc(plan.already_done ?? 0)} already existed, ${esc(plan.deferred_to_next_run ?? 0)} deferred by the per-run cap.</p>
  ${failedList ? `<div class="box"><h3 style="color:var(--bad)">Failed this run</h3><ul>${failedList}</ul></div>` : ''}
  ${waitingList ? `<div class="box"><h3>Waiting on your picks (run again after copying)</h3><ul>${waitingList}</ul></div>` : ''}
  ${sections || '<p class="sub">No images yet.</p>'}
</main></body></html>`;

const galleryPath = path.join(GEN_DIR, 'index.html');
fs.writeFileSync(galleryPath, html);
console.log('Gallery:', galleryPath);

return [{ json: {
  generated: ok.length,
  failed: failed.map(f => `${f.id} ${f.view || ''} v${f.variant}: ${f.error}`),
  already_done: plan.already_done ?? 0,
  deferred_to_next_run: plan.deferred_to_next_run ?? 0,
  waiting_on_picks: (plan.waiting_on_picks || []).map(w => `${w.id} (${w.stage}) needs ${w.needs.join(', ')}`),
  gallery: winPath(galleryPath),
  picked_folder: winPath(path.join(ART_DIR, 'picked'))
} }];
